/**Idioma en el que hay que escribir AHORA MISMO.Tres niveles, de más específico a más general:  1. El que haya forzado `conIdiomaDe()` — un correo dirigido a alguien     concreto se escribe en SU idioma, no en el de quien lanzó el proceso.  2. La preferencia guardada de esa persona, si se pasa su correo.  3. El idioma del script, que es el del menú de la hoja./
function obtenerIdiomaUsuario(email) {
  if (_IDIOMA_FORZADO) return _IDIOMA_FORZADO;

  if (email) {
    try {
      const propio = normalizarIdioma(
        PropertiesService.getScriptProperties().getProperty(claveIdiomaDe(email)));
      if (propio) return propio;
    } catch (e) { /* se sigue al idioma del script */ }
  }

  if (_CACHE_IDIOMA) return _CACHE_IDIOMA;
  try {
    _CACHE_IDIOMA = normalizarIdioma(
      PropertiesService.getScriptProperties().getProperty("APP_LANG")) || "ES";
  } catch (e) {
    _CACHE_IDIOMA = "ES";
  }
  return _CACHE_IDIOMA;
}

