/** Toast seguro: no rompe ejecuciones headless (triggers, webapp). */
function notificarUsuario(mensaje, titulo = "Videoteca", segundos = 4) {
  try {
    SpreadsheetApp.getActiveSpreadsheet().toast(mensaje, titulo, segundos);
  } catch (e) {
    registrarLogActividad("Toast", mensaje, "DEBUG");
  }
}

/** Alerta segura: degrada a log si no hay interfaz disponible.

Alerta segura: degrada a log si no hay interfaz disponible. */
function alertarUsuario(mensaje, titulo = "Videoteca") {
  try {
    const ui = SpreadsheetApp.getUi();
    ui.alert(titulo, mensaje, ui.ButtonSet.OK);
  } catch (e) {
    registrarLogActividad("Alerta", titulo + " :: " + mensaje, "INFO");
  }
}

function hayInterfazDisponible() {
  try { SpreadsheetApp.getUi(); return true; } catch (e) { return false; }
}

