  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let dlq = ss.getSheetByName("_Dead_Letter_Queue");
  const col = CABECERAS_DLQ.indexOf("HTTP Code") + 1;
  if (!dlq) {
    dlq = ss.insertSheet("_Dead_Letter_Queue");
    dlq.getRange(1, 1, 1, CABECERAS_DLQ.length).setValues([CABECERAS_DLQ])
      .setFontWeight("bold").setBackground("#991b1b").setFontColor("#ffffff");
    dlq.setFrozenRows(1);
    dlq.hideSheet();
  } else if (dlq.getRange(1, col).getValue() !== "HTTP Code") {
    /* Migración desde el esquema de 8 columnas de v2026.3.5. Las posiciones
       salen de CABECERAS_DLQ y no de letras escritas a mano: «F1» dejaría de
       ser la columna correcta en cuanto alguien añadiera un campo antes. */
    dlq.insertColumnsAfter(col - 1, 1);
    dlq.getRange(1, col).setValue("HTTP Code")
      .setFontWeight("bold").setBackground("#991b1b").setFontColor("#ffffff");
  }
  return dlq;
}

/**¿Ya está esta fila en la cola? Devuelve su número de fila en la DLQ, o 0.Se compara por URL además de por número de fila porque el número solo nobasta: si alguien inserta o borra filas del catálogo, la 148 de ayer es otrovideo hoy, y actualizar su entrada borraría el problema real./
function buscarFilaEnDLQ(dlq, filaNum, url) {
  const ultima = dlq.getLastRow();
  if (ultima < 2) return 0;
  const valores = dlq.getRange(2, 2, ultima - 1, 2).getValues();   // Fila Original + URL
  const objetivo = (url || "").toString().trim();
  for (let i = 0; i < valores.length; i++) {
    if (Number(valores[i][0]) === Number(filaNum) &&
        (valores[i][1] || "").toString().trim() === objetivo) return i + 2;
  }
  return 0;
}

/**[MEJORA 9] Aísla un registro fallido guardando además el código HTTP para diagnóstico.

Anota en una fila que falta configurar algo, sin contarla como fallo.«No tengo la credencial para leer este video» y «este video está roto» soncosas distintas con soluciones distintas, y `gestionarErrorFila` las tratabaigual: tres pasadas y a la cola de fallos. Un video público de Twitch acababaaislado por una clave que nadie había puesto. Aquí solo se deja escrito elmotivo; el Estado no se toca, así que la siguiente pasada lo vuelve aintentar en cuanto la credencial exista./
function anotarPendienteDeConfiguracion(filaNum, mensaje, filaMem = null) {
  escribirEnFila(filaNum, filaMem, IDX.ERROR,
    (mensaje || "Falta configuración").toString().slice(0, 255));
  logWarn("Configuración", `Fila ${filaNum} en espera: ${mensaje}`);
}

/**Colapsa las entradas repetidas que ya están en la cola.Para las colas que crecieron antes de que `registrarFallaEnDLQ` supieraactualizar en vez de añadir. Se conserva la entrada MÁS RECIENTE de cada(fila, URL) —su causa es la vigente— y su contador de intentos pasa a ser lasuma de las copias, que es la información que las copias contenían.

Aparta una fila cuya URL no es un video, con el motivo escrito al lado.No es un fallo ni va a la cola: no hay nada que reintentar. Se marca«⚪ Descartado» —un estado que ya existe y que la ingesta respeta— y elmotivo queda visible en la columna de error para que se pueda corregir laURL y devolverla a «🟡 Pendiente» a mano./
function marcarEnlaceNoProcesable(filaNum, motivo, filaMem = null) {
  exigirOrigenInterno("marcarEnlaceNoProcesable");
  escribirEnFila(filaNum, filaMem, IDX.ERROR, (motivo || "").toString().slice(0, 255));
  escribirEnFila(filaNum, filaMem, IDX.ESTADO, "⚪ Descartado");
  PropertiesService.getUserProperties().deleteProperty("FAIL_COUNT_" + filaNum);
  logWarn("Ingesta", `Fila ${filaNum} apartada: ${motivo}`);
}

