let _ventanaFilas = null;

/**Límites reales de un recorrido, teniendo en cuenta la ventana si la hay.Punto único: si esto se calculara en cada sitio, un día uno de ellos aplicaríala ventana y otro no, y el recorrido «desde la fila 500» tocaría la 2.

Recorre el catálogo en bloques para limitar el consumo de memoria.callback(datos, filaInicioReal, hoja) devuelve true si mutó el bloque./
/* [v2.6.10] Ventana de filas activa, o null.
   Existe para poder decir «haz esto, pero solo del renglón 500 en adelante» sin
   añadirle un parámetro a cada una de las funciones que recorren el catálogo —y
   sin que cada una lo interprete a su manera—. Se pone y se quita en
   conVentanaDeFilas(); nadie más debería tocarla. */
let _ventanaFilas = null;

/**Límites reales de un recorrido, teniendo en cuenta la ventana si la hay.Punto único: si esto se calculara en cada sitio, un día uno de ellos aplicaríala ventana y otro no, y el recorrido «desde la fila 500» tocaría la 2./
function limitesRecorridoCatalogo(ultFilaReal) {
  const desde = _ventanaFilas ? Math.max(2, _ventanaFilas.desde) : 2;
  const hasta = _ventanaFilas && _ventanaFilas.hasta
    ? Math.min(ultFilaReal, _ventanaFilas.hasta)
    : ultFilaReal;
  return { desde: desde, hasta: hasta };
}

/**Ejecuta `fn` con el catálogo acotado a un rango de filas.El `finally` NO es una precaución de estilo: si la ventana se quedara puestaal fallar algo, todo lo que se ejecutara después en esa misma invocación—incluido un recorrido que cree que está mirando el catálogo entero— veríasolo un trozo, y no habría ningún error a la vista. Un filtro global que seescapa es de los fallos más caros que existen: los números salen, y salen mal.@param {number} desde  primera fila de datos (mínimo 2)@param {number} hasta  última fila, o 0 / null para llegar hasta el final

Devuelve la fila completa del catálogo para un ID de video, o null. */
function buscarFilaCatalogoPorId(idVideo) {
  if (!idVideo) return null;
  let encontrada = null;
  let numeroFila = -1;
  iterarCatalogoPorBloques(function (datos, inicio) {
    for (let i = 0; i < datos.length; i++) {
      if ((datos[i][IDX.ID] || "").toString().trim() === idVideo.toString().trim()) {
        encontrada = datos[i];
        numeroFila = inicio + i;
        return false;
      }
    }
    return false;
  });
  return encontrada ? { fila: encontrada, numeroFila: numeroFila } : null;
}

