function idiomaDesdeCodigoPlataforma(codigo) {
  const c = (codigo || "").toString().trim().toLowerCase();
  if (!c) return "";
  const base = c.split(/[-_]/)[0];
  const M = { es: "ES", en: "EN", pt: "PT", fr: "FR", de: "DE", it: "IT" };
  return M[base] || "";
}

/**¿En qué idioma está este video?Sustituye a una versión que miraba siete palabras y, si no encontrabaninguna, respondía «ES». Con medio catálogo en inglés eso significaba que lacolumna decía «ES» en casi todas las filas: no se podía filtrar por idiomaporque no había nada que filtrar, y además arrastraba a la clasificación—«tutorial» contaba como inglés aunque en español se diga igual—.Ahora se vota. Cada palabra funcional encontrada suma un punto para suidioma; las letras exclusivas (ñ, ã, ß) suman más porque no se cuelan porcasualidad. Gana quien saque más puntos, y SOLO si le saca ventaja alsegundo: dos idiomas empatados significan que el título no da para decidir.Cuando no hay señal suficiente devuelve «Indeterminado» en vez de inventarse«ES». Un dato que dice «no lo sé» se puede filtrar, revisar y corregir; unoque miente no se nota nunca.@param {string} titulo@param {string} defaultLang  lo que declara la plataforma, si lo declara@param {string} [descripcion] texto adicional: más palabras, mejor voto

Cuánta descripción se mira para clasificar. */
const DESCRIPCION_MAX_CLASIFICAR = 600;

/**Deja el texto en condiciones de ser clasificado.Tres decisiones, todas por la misma razón —que el pie de la descripción nodecide el tema del video—: 1. Se borran URLs, arrobas y correos ANTES de normalizar. Si no, cada    enlace deja regados en el texto trozos como «https», «www», «com» o el    nombre del dominio, y esos trozos compiten con el título. 2. Se recorta la descripción. Las descripciones de YouTube arrastran    patrocinios, listas de capítulos y créditos que hablan de cualquier cosa    menos del contenido; lo que describe el video está siempre al principio. 3. El título va entero y sin recortar, porque es la señal buena.[v2.6.8] La cuarta decisión, que era un error: las etiquetas y las mencionesse BORRABAN enteras. `.replace(/[@#]\w+/g, " ")` no quitaba el símbolo, sellevaba también la palabra. En un catálogo de YouTube eso es tirar a la basurala mejor señal que existe: de los 53 títulos pendientes que hablan de Odoo,los 53 lo dicen únicamente dentro de «#Odoo», «#odoo18», «#OdooApps» o«@Odoo». La regla «odoo» no podía coincidir con un texto del que se habíaborrado la palabra «odoo», así que quedaban «Sin clasificar» y de ahí pasabana la Fase 2, a gastar IA para averiguar algo que estaba escrito en el título.Ahora se cae el símbolo y se conserva la palabra, y además se parte laetiqueta por sus costuras —mayúscula interior y frontera letra/número— porquelas etiquetas van pegadas: «#OdooApps» da «odoo apps» sin dejar de dar«odooapps». Se emiten las dos formas, la entera y la troceada, y decide laregla. Esto NO abre la clasificación: el vocabulario sigue cerrado yCLAVES_NO_DISCRIMINAN sigue filtrando el ruido. Lo único que cambia es que elruido ahora tiene que ser descartado en vez de no llegar nunca.

¿Es un video musical? Se decide con lo que ya tenemos, en este orden: 1. La CATEGORÍA que devolvió YouTube. Es la señal buena: la pone la propia    plataforma y no depende de cómo esté escrito el título. Ya se guardaba en    la hoja sin usarse para nada. 2. Marcas inequívocas del título, para los videos que aún no tienen categoría    —los recién pegados a mano— o los que vienen de otra plataforma.Deliberadamente NO se usa la palabra suelta «música»: un video titulado«Cómo poner música de fondo en el punto de venta» es de POS, no un musical.Ante la duda, no es musical: marcarlo mal lo saca de la capacitación.@param {string} titulo@param {string} categoriaYouTube  el valor de la columna «Categoría YouTube»/
function pareceVideoMusical(titulo, categoriaYouTube) {
  const cat = (categoriaYouTube || "").toString().trim();
  if (cat && CATEGORIAS_YT_MUSICA.indexOf(cat) !== -1) return true;

  const t = normalizarBusqueda(titulo);
  if (!t) return false;
  const MARCAS = [
    "video oficial", "official video", "official music video", "audio oficial",
    "official audio", "lyric video", "video lyric", "letra oficial",
    "videoclip", "en vivo concierto", "live session", "cover acustico"
  ];
  if (MARCAS.some(m => t.indexOf(m) !== -1)) return true;
  /* Los canales de VEVO se escriben pegados al nombre del artista
     («ShakiraVEVO»), así que aquí no vale el límite de palabra. «vevo» es una
     cadena lo bastante rara como para no aparecer por accidente. */
  return t.indexOf("vevo") !== -1;
}

/**¿Esta fila del catálogo es contenido CERTIFICABLE?Gobierna módulos, exámenes y Fase 2. Esto NO es configurable a propósito: unexamen sobre la letra de una canción no certifica ninguna competencia, y elcertificado que salga de ahí no significa nada. Lo que sí se puede activar esla extracción de la letra —ver filaAdmiteTranscripcion()—, que es otra cosa.

¿Esta fila del catálogo es contenido CERTIFICABLE?Gobierna módulos, exámenes y Fase 2. Esto NO es configurable a propósito: unexamen sobre la letra de una canción no certifica ninguna competencia, y elcertificado que salga de ahí no significa nada. Lo que sí se puede activar esla extracción de la letra —ver filaAdmiteTranscripcion()—, que es otra cosa./
function filaEsCertificable(r) {
  if (!r) return false;

  /* [v2] La faceta manda. Es la única respuesta a «¿sirve para formar?», y es
     independiente de «¿de qué trata?»: un video de astronomía puede estar
     perfectamente clasificado en Ciencia y Tecnología / Astronomía y aun así
