/**[v2.6.12] Identificador de un video de Tencent (v.qq.com).El «vid» aparece en dos formas de URL: la de página suelta(v.qq.com/x/page/<vid>.html) y la de episodio dentro de una serie(v.qq.com/x/cover/<cid>/<vid>.html). En la segunda se toma el SEGUNDOidentificador: el primero es la serie entera, y quedarse con él haría quetodos los episodios compartieran fila.

[v2.6.12] Identificador de un video de Tencent (v.qq.com).El «vid» aparece en dos formas de URL: la de página suelta(v.qq.com/x/page/<vid>.html) y la de episodio dentro de una serie(v.qq.com/x/cover/<cid>/<vid>.html). En la segunda se toma el SEGUNDOidentificador: el primero es la serie entera, y quedarse con él haría quetodos los episodios compartieran fila./
function obtenerIdTencent(url) {
  const str = (url || "").toString().trim();
  if (!str) return "";
  const cover = str.match(/v\.qq\.com\/x\/cover\/[A-Za-z0-9]+\/([A-Za-z0-9]+)\.html/i);
  if (cover && cover[1]) return cover[1];
  const page = str.match(/v\.qq\.com\/x\/page\/([A-Za-z0-9]+)\.html/i);
  if (page && page[1]) return page[1];
  const vid = str.match(/[?&]vid=([A-Za-z0-9]+)/i);
  if (vid && vid[1] && /v\.qq\.com/i.test(str)) return vid[1];
