/** Marca como VALIDADA y CURADA todas las preguntas de un módulo.

Marca como VALIDADA y CURADA todas las preguntas de un módulo. */
function promoverBancoAValidado(moduloId) {
  exigirOrigenInterno("promoverBancoAValidado");
  const sheet = obtenerHojaClaves();
  if (sheet.getLastRow() < 2) return 0;
  const rango = sheet.getRange(2, 1, sheet.getLastRow() - 1, CABECERAS_CLAVES.length);
  const datos = rango.getValues();
  let validadas = 0;
  for (let i = 0; i < datos.length; i++) {
    if ((datos[i][CLAVE.MODULO] || "").toString().trim() !== moduloId) continue;
    if ((datos[i][CLAVE.VALIDACION] || "").toString() === VALIDACION.RETIRADA) continue;
    datos[i][CLAVE.VALIDACION] = VALIDACION.VALIDADA;
    datos[i][CLAVE.PROCEDENCIA] = PROCEDENCIA.CURADA;
    validadas++;
  }
  if (validadas > 0) {
    rango.setValues(datos);
    invalidarCacheBanco(moduloId);   // el banco cacheado ya no refleja la hoja
    limpiarMemoEjecucion();
  }
  logInfo("Banco", `${validadas} preguntas del módulo ${moduloId} promovidas a VALIDADA.`);
  return validadas;
}

