/**Reduce un user-agent a «marca de navegador · sistema».El user-agent completo es una huella: dice versiones exactas de sistema y denavegador, y sirve para identificar un equipo concreto. Para el panel no hacefalta nada de eso — solo distinguir «el portátil del trabajo» de «el móvil» —,así que se recorta aquí, en el servidor, y lo largo no sale nunca de la hoja.El orden de las comprobaciones importa: Edge y Opera se anuncian TAMBIÉN comoChrome, y Chrome se anuncia también como Safari. Hay que ir de lo másespecífico a lo más genérico o todo el mundo acaba siendo «Chrome»./
function etiquetaDispositivo(agente) {
  const ua = (agente || "").toString();
  if (!ua.trim()) return "Desconocido";

  let navegador = "";
  if (/Edg[A-Z]?\//i.test(ua) || /\bEdge\//i.test(ua)) navegador = "Edge";
  else if (/OPR\//i.test(ua) || /\bOpera\//i.test(ua)) navegador = "Opera";
  else if (/SamsungBrowser\//i.test(ua)) navegador = "Samsung Internet";
  else if (/\bFirefox\//i.test(ua) || /\bFxiOS\//i.test(ua)) navegador = "Firefox";
  else if (/\bCriOS\//i.test(ua)) navegador = "Chrome";
  else if (/\bChrome\//i.test(ua) || /\bChromium\//i.test(ua)) navegador = "Chrome";
  else if (/\bSafari\//i.test(ua)) navegador = "Safari";

  let sistema = "";
  if (/\biPhone\b/i.test(ua)) sistema = "iPhone";
  else if (/\biPad\b/i.test(ua)) sistema = "iPad";
  else if (/\bAndroid\b/i.test(ua)) sistema = "Android";
  else if (/\bCrOS\b/i.test(ua)) sistema = "ChromeOS";
  else if (/Windows NT|\bWindows\b/i.test(ua)) sistema = "Windows";
  else if (/Mac OS X|\bMacintosh\b/i.test(ua)) sistema = "macOS";
  else if (/\bLinux\b/i.test(ua)) sistema = "Linux";

  if (navegador && sistema) return navegador + " · " + sistema;
  if (navegador) return navegador;
  if (sistema) return sistema;
  return "Desconocido";
}

/**Dispositivos distintos por correo vistos dentro de una ventana.Devuelve un mapa correo → nº de fingerprints distintos. Se cuenta, no selista: el panel necesita saber si alguien entra desde tres sitios a la vez,no cuáles son.

Dispositivos distintos por correo vistos dentro de una ventana.Devuelve un mapa correo → nº de fingerprints distintos. Se cuenta, no selista: el panel necesita saber si alguien entra desde tres sitios a la vez,no cuáles son./
function contarDispositivosEnVentana(desdeMs) {
  const conteo = {};
  try {
    const hoja = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("_Dispositivos_Conocidos");
    if (!hoja || hoja.getLastRow() < 2) return conteo;
    const vistos = {};
    hoja.getRange(2, 1, hoja.getLastRow() - 1, DISPO_COLS).getValues().forEach(function (d) {
      const correo = (d[DISPO.CORREO] || "").toString().toLowerCase().trim();
      if (!correo) return;
      if (milisegundosDe(d[DISPO.ULTIMA]) < desdeMs) return;
      const fp = (d[DISPO.FINGERPRINT] || "").toString().trim() || "sin-huella";
      if (!vistos[correo]) vistos[correo] = {};
      if (vistos[correo][fp]) return;
      vistos[correo][fp] = true;
      conteo[correo] = (conteo[correo] || 0) + 1;
    });
  } catch (e) {
    logWarn("Actividad", "No se pudieron contar dispositivos: " + e.message);
  }
  return conteo;
}

/**Intentos EN_CURSO por correo. Es lo que permite decir «está examinándose» sininventar un estado nuevo: la hoja `_Intentos` ya lo sabe.Devuelve mapa correo → { moduloId, inicioMs }.

Intentos EN_CURSO por correo. Es lo que permite decir «está examinándose» sininventar un estado nuevo: la hoja `_Intentos` ya lo sabe.Devuelve mapa correo → { moduloId, inicioMs }./
function examenesEnCursoPorCorreo() {
  const abiertos = {};
  try {
    const hoja = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("_Intentos");
    if (!hoja || hoja.getLastRow() < 2) return abiertos;
    hoja.getRange(2, 1, hoja.getLastRow() - 1, INT_COLS).getValues().forEach(function (t) {
      if ((t[INT.ESTADO] || "").toString().trim() !== ESTADO_INTENTO.EN_CURSO) return;
      const correo = (t[INT.EMAIL] || "").toString().toLowerCase().trim();
      if (!correo) return;
      const inicioMs = milisegundosDe(t[INT.INICIO]);
      // Si alguien tuviera dos intentos abiertos (no debería), manda el último.
      if (abiertos[correo] && abiertos[correo].inicioMs >= inicioMs) return;
      abiertos[correo] = { moduloId: (t[INT.MODULO] || "").toString().trim(), inicioMs: inicioMs };
    });
  } catch (e) {
    logWarn("Actividad", "No se pudieron leer los intentos en curso: " + e.message);
  }
  return abiertos;
}

/**[ADMIN] Quién ha dejado señal en los últimos `minutos` y sobre qué contenido.Una persona aparece UNA sola vez aunque tenga muchas filas de progreso: lo queinteresa administrar es la persona, no la fila. Su señal es la más reciente delas que tenga, y `haceMinutos` viaja calculado desde el servidor para que elportal no dependa del reloj del navegador.Un examen en curso también es una señal: quien está examinándose está activoaunque no haya ningún video reproduciéndose.@param {string} token   token con scope admin@param {number} minutos ventana; por defecto 30, acotada entre 5 y 1440

[ADMIN] Desde qué dispositivos entra una persona.Devuelve etiquetas legibles, no huellas: ni la IP anonimizada ni eluser-agent completo salen de la hoja. Con «Chrome · Windows, usado hace dosdías» el administrador ya puede detectar una cuenta compartida, que es elúnico motivo legítimo para mirar esto./
function obtenerDispositivosUsuario(token, correo) {
  validarTokenConScope(token, "admin");

  const email = (correo || "").toString().toLowerCase().trim();
  const salida = { correo: email, total: 0, dispositivos: [] };
  if (!email) return salida;

  const limiteReciente = Date.now() - DISPOSITIVO_RECIENTE_DIAS * 86400000;

  try {
    const hoja = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("_Dispositivos_Conocidos");
    if (!hoja || hoja.getLastRow() < 2) return salida;

    hoja.getRange(2, 1, hoja.getLastRow() - 1, DISPO_COLS).getValues().forEach(function (d) {
      if ((d[DISPO.CORREO] || "").toString().toLowerCase().trim() !== email) return;
      const ultimaMs = milisegundosDe(d[DISPO.ULTIMA]);
      salida.dispositivos.push({
        etiqueta: etiquetaDispositivo(d[DISPO.AGENTE]),
        primeraVez: formatearFecha(d[DISPO.PRIMERA]),
        ultimaVez: formatearFecha(d[DISPO.ULTIMA]),
        usos: parseInt(d[DISPO.USOS], 10) || 0,
        esReciente: ultimaMs > 0 && ultimaMs >= limiteReciente,
        _orden: ultimaMs
      });
    });
  } catch (e) {
    logWarn("Actividad", "No se pudieron leer los dispositivos de " + email + ": " + e.message);
    return salida;
  }

  salida.dispositivos.sort(function (x, y) { return y._orden - x._orden; });
  salida.dispositivos.forEach(function (d) { delete d._orden; });
  salida.total = salida.dispositivos.length;
  return salida;
}

