function obtenerPanelAdministracion(token) {
  validarTokenConScope(token, "admin");

  const catalogo = panelSeccionCatalogo();
  const certificados = panelCertificados();
  const modulos = panelSeccionModulos(certificados);
  const personas = panelSeccionPersonas(certificados);
  const cola = panelEstadoCola();
  const sistema = panelSeccionSistema(cola);

  return {
    // La versión viaja en el panel a propósito: es la pantalla que el
    // administrador abre a diario, y es donde se nota si el Codigo.gs
    // desplegado no es el que corresponde al portal que está viendo.
    version: VERSION_SCRIPT,
    catalogo: catalogo,
    modulos: modulos,
    personas: personas,
    sistema: sistema,
    alertas: panelAlertas(catalogo, modulos, sistema, cola)
  };
